referenceSolutionTemplate:
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    char *name;
    int score;
    struct Node *next;
} Node;

Node *add_last(Node *head, char *name, int score) {
    Node *fresh = malloc(sizeof(Node));
    if (fresh == NULL) {
        return head;
    }
    fresh->name = name;
    fresh->score = score;
    fresh->next = NULL;
    if (head == NULL) {
        return fresh;
    }
    Node *p = head;
    while (p->next != NULL) {
        p = p->next;
    }
    p->next = fresh;
    return head;
}

void print_all(Node *head) {
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%s：%d 分\n", p->name, p->score);
    }
}

int main(void) {
    Node *head = NULL;
    head = add_last(head, "{n1}", {s1});
    head = add_last(head, "{n2}", {s2});
    head = add_last(head, "{n3}", {s3});
    print_all(head);
    return 0;
}
